import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class E {

	static long MOD=998244353;
	static long[] factArr, invFactArr;

	public static void main(String[] args) {
		initializeFactorials();
		InputReader in=new InputReader();
		try {
		int totalN=in.nextInt(), totalK=in.nextInt();
		if (totalK==0) {
			System.out.println(factArr[totalN]);
			return;
		}
		if (totalK>=totalN) {
			System.out.println(0);
			return;
		}
		int remaining=totalN-totalK;
		long assignWays=calculatePower(remaining, totalN);
		long pickWays=calculateCombination(totalN, remaining);
		long result=mult(assignWays, pickWays);
		System.out.println(mult(result, 2));
		}
		catch(Throwable t) {
			System.out.println(0);
		}
	}

	static long calculatePower(int base, long exp) {
		long total=0;
		for (int i=0; i<base; i++) {
			long term=fastPow(base-i, exp)*calculateCombination(base, i);
			if (i%2==0) {
				total=add(total, term);
			} else {
				total=sub(total, term);
			}
		}
		return total;
	}

	static void initializeFactorials() {
		factArr=new long[1_000_000];
		invFactArr=new long[1_000_000];
		factArr[0]=invFactArr[0]=1;
		for (int i=1; i<factArr.length; i++) factArr[i]=mul(factArr[i-1], i);
		invFactArr[factArr.length-1]=fastPow(factArr[factArr.length-1], MOD-2);
		for (int i=invFactArr.length-2; i>=0; i--) invFactArr[i]=mul(invFactArr[i+1], i+1);
	}

	static long calculateCombination(int n, int k) {
		return mul(factArr[n], mul(invFactArr[k], invFactArr[n-k]));
	}

	static long add(long a, long b) {
		return (a+b)%MOD;
	}

	static long sub(long a, long b) {
		return ((a-b)%MOD+MOD)%MOD;
	}

	static long mul(long a, long b) {
		return a*b%MOD;
	}

	static long fastPow(long base, long exp) {
		if (exp==0) return 1;
		long half=fastPow(base, exp/2);
		if (exp%2==0) return mul(half, half);
		return mul(half, mul(half, base));
	}

	static class InputReader {
		BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st=new StringTokenizer("");

		public String next() {
			while (!st.hasMoreElements())
				try {
					st=new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}
	}
}
